#pragma once

#include <stdbool.h>
#include <stdlib.h>

// The Go core's C ABI, statically linked into the Runner binary.
//
// The Go //export stubs (core/lib.go, signatures fixed by the Go source) and
// the host callbacks (core/bride.c). Referenced directly from Swift through
// the bridging header — no dlsym, no runtime symbol lookup.
//
// Generated by `go build -buildmode=c-archive` and linked into Runner by the
// OTHER_LDFLAGS -force_load in ios/Flutter/*.xcconfig.

// Go //export stubs
extern void invokeMethod(void *callback, char *params);
extern bool startTUN(void *callback, int fd, char *stack, char *address, char *dns);
extern void quickSetup(void *callback, char *initParams, char *setupParams);
extern void setEventListener(void *listener);
extern void stopTun(void);
extern void forceGC(void);
extern void updateDns(char *dns);
extern char *getTraffic(bool onlyStatisticsProxy);
extern char *getTotalTraffic(bool onlyStatisticsProxy);
